/* =========================================================
   GENERAL
   ========================================================= */

body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10px;
    color: #222;
    margin: 0;
    padding: 0;
}

.purchase-invoice {
    width: 100%;
}


/* =========================================================
   HEADER
   ========================================================= */

.header {
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: flex-start;

    border-bottom: 2px solid #222;

    padding-bottom: 12px;
    margin-bottom: 12px;
}


/* =========================================================
   COMPANY SECTION REMOVED
   ========================================================= */

.company {
    display: none;
}

.company-logo {
    display: none !important;
}

.company-name {
    display: none !important;
}

.company-address {
    display: none !important;
}

.company-tax {
    display: none !important;
}


/* =========================================================
   PURCHASE INVOICE HEADER
   ========================================================= */

.invoice-heading {
    width: 100%;
    text-align: center;
}

.invoice-title {
    font-size: 18px;
    font-weight: bold;

    margin-bottom: 8px;

    text-align: center;
}

.header-info {
    width: 45%;

    margin-left: auto;
    margin-right: auto;

    border-collapse: collapse;
}

.header-info td {
    padding: 3px;

    text-align: right;

    font-size: 9px;
}

.header-info td:first-child {
    width: 50%;
}


/* =========================================================
   SUPPLIER / BUYER / SHIPPING ADDRESS
   ========================================================= */

.party-table {
    width: 100%;

    border-collapse: collapse;

    margin-bottom: 12px;
}

.party-box {
    width: 33.333%;

    border: 1px solid #bbb;

    padding: 8px;

    vertical-align: top;

    font-size: 9px;

    line-height: 1.25;
}


/* =========================================================
   BOX TITLE
   ========================================================= */

.box-title {
    font-weight: bold;

    font-size: 9px;

    margin-bottom: 5px;

    text-transform: uppercase;
}


/* =========================================================
   PARTY NAME
   ========================================================= */

.party-name {
    font-size: 10px;

    font-weight: bold;

    margin-bottom: 4px;

    line-height: 1.25;
}


/* =========================================================
   SUPPLIER ADDRESS
   ========================================================= */

.address {
    margin-top: 2px;

    font-size: 9px;

    line-height: 1.25;
}


/* =========================================================
   SHIPPING ADDRESS
   ========================================================= */

.shipping-address {
    margin-top: 2px;

    font-size: 9px;

    line-height: 1.25;

    white-space: pre-line;
}

.address br {
    line-height: 1.25;
}

.shipping-address br {
    line-height: 1.25;
}


/* =========================================================
   PARTY TAX
   ========================================================= */

.party-tax {
    margin-top: 5px;

    font-size: 8px;

    line-height: 1.25;
}


/* =========================================================
   SECTION TITLE
   ========================================================= */

.section-title {
    font-size: 11px;

    font-weight: bold;

    text-transform: uppercase;

    border-bottom: 1px solid #333;

    padding-bottom: 4px;

    margin-top: 12px;

    margin-bottom: 0;
}


/* =========================================================
   INVOICE INFORMATION
   ========================================================= */

.reference-table {
    width: 100%;

    border-collapse: collapse;

    margin-bottom: 12px;
}

.reference-table td {
    width: 25%;

    border: 1px solid #ccc;

    padding: 6px;

    vertical-align: top;

    line-height: 1.35;

    font-size: 9px;
}


/* =========================================================
   ITEMS
   ========================================================= */

.items {
    width: 100%;

    border-collapse: collapse;

    margin-bottom: 12px;

    table-layout: fixed;
}

.items th {
    background: #eeeeee;

    border: 1px solid #999;

    padding: 6px 4px;

    font-size: 9px;

    text-align: center;

    font-weight: bold;

    vertical-align: middle;
}

.items td {
    border: 1px solid #ccc;

    padding: 6px 4px;

    vertical-align: top;

    font-size: 9px;

    word-wrap: break-word;
}


/* =========================================================
   ITEM COLUMN WIDTHS
   ========================================================= */

.sr {
    width: 4%;
}

.item-code {
    width: 13%;
}

.description {
    width: 27%;
}

.qty {
    width: 7%;
}

.uom {
    width: 7%;
}

.rate {
    width: 15%;
}

.tax {
    width: 10%;
}

.amount {
    width: 17%;
}


/* =========================================================
   ALIGNMENT
   ========================================================= */

.center {
    text-align: center;
}

.right {
    text-align: right;
}

.left {
    text-align: left;
}

.small {
    font-size: 8px;
}


/* =========================================================
   COMPANY CURRENCY
   ========================================================= */

.main-currency {
    font-size: 9px;

    font-weight: normal;

    white-space: nowrap;
}

.main-currency strong {
    font-weight: bold;
}


/* =========================================================
   SUPPLIER CURRENCY
   ========================================================= */

.secondary-value {
    font-size: 8px;

    color: #555;

    margin-top: 3px;

    white-space: nowrap;
}

.secondary-value strong {
    font-weight: bold;
}


/* =========================================================
   TOTALS
   ========================================================= */

.totals-wrapper {
    width: 100%;

    margin-top: 8px;
}

.totals {
    width: 45%;

    margin-left: auto;

    border-collapse: collapse;
}

.totals td {
    border: 1px solid #ccc;

    padding: 6px;

    font-size: 9px;

    vertical-align: top;
}

.totals td:first-child {
    font-weight: bold;

    text-align: left;
}

.totals td:last-child {
    text-align: right;

    white-space: nowrap;
}


/* =========================================================
   TOTAL VALUES
   ========================================================= */

.main-total {
    font-size: 9px;

    white-space: nowrap;
}

.main-total strong {
    font-weight: bold;
}

.secondary-total {
    font-size: 8px;

    color: #555;

    margin-top: 3px;

    font-weight: normal;

    white-space: nowrap;
}

.secondary-total strong {
    font-weight: bold;
}


/* =========================================================
   GRAND TOTAL
   ========================================================= */

.grand-total {
    font-size: 11px !important;

    font-weight: bold;

    background: #eeeeee;
}

.grand-total-value {
    font-size: 11px;

    font-weight: bold;

    white-space: nowrap;
}

.grand-secondary {
    font-size: 8px;
}


/* =========================================================
   COMPANY CURRENCY SUMMARY
   ========================================================= */

.base-summary {
    margin-top: 8px;

    padding: 7px;

    border: 1px solid #ccc;

    font-size: 9px;

    line-height: 1.5;
}


/* =========================================================
   SUPPLIER CURRENCY SUMMARY
   ========================================================= */

.supplier-summary {
    margin-top: 6px;

    padding: 7px;

    border: 1px solid #ccc;

    font-size: 9px;

    line-height: 1.5;
}


/* =========================================================
   AMOUNT IN WORDS
   ========================================================= */

.amount-words {
    margin-top: 10px;

    padding: 7px;

    border: 1px solid #ccc;

    line-height: 1.5;

    font-size: 9px;
}


/* =========================================================
   TAX SUMMARY
   ========================================================= */

.tax-table {
    width: 100%;

    border-collapse: collapse;

    margin-top: 5px;

    margin-bottom: 10px;
}

.tax-table th {
    background: #eeeeee;

    border: 1px solid #aaa;

    padding: 5px;

    font-size: 9px;

    text-align: left;

    font-weight: bold;
}

.tax-table td {
    border: 1px solid #ccc;

    padding: 5px;

    font-size: 9px;
}


/* =========================================================
   REMARKS
   ========================================================= */

.remarks {
    margin-top: 12px;

    border: 1px solid #ccc;

    padding: 7px;

    line-height: 1.5;

    font-size: 9px;
}


/* =========================================================
   FOOTER
   ========================================================= */

.footer {
    margin-top: 25px;

    padding-top: 7px;

    border-top: 1px solid #999;

    display: flex;

    justify-content: space-between;

    font-size: 9px;
}


/* =========================================================
   PRINT
   ========================================================= */

@media print {

    body {
        font-size: 9px;
    }

    .purchase-invoice {
        width: 100%;
    }

    .items th,
    .grand-total,
    .tax-table th {

        background: #eeeeee !important;

        -webkit-print-color-adjust: exact;

        print-color-adjust: exact;
    }

    .items {
        page-break-inside: auto;
    }

    .items tr {
        page-break-inside: avoid;

        page-break-after: auto;
    }

    .party-table,
    .reference-table,
    .tax-table {

        page-break-inside: avoid;
    }

    .party-box {
        page-break-inside: avoid;
    }

    .company-logo {
        display: none !important;
    }

    .company-name {
        display: none !important;
    }

    .company-address {
        display: none !important;
    }

    .secondary-value,
    .secondary-total {

        font-size: 8px !important;
    }

    .address,
    .shipping-address {

        line-height: 1.25 !important;
    }

    .address br,
    .shipping-address br {

        line-height: 1.25 !important;
    }

}

